/**
 * Updates one alert rule by its stable ID. Supports label overrides, drop/restore toggles (platform rules only), and classification label updates. Same mutation semantics as BulkUpdateAlertRules for a single ID. When both classification and labels are set, classification is applied first, then labels. These steps are not atomic: if the label update fails after classification succeeded, the classification change remains applied and the request returns an error.
 * @summary Update a single alert rule
 */
export const updateAlertRule = async (
  ruleId: string,
  updateAlertRuleRequest: UpdateAlertRuleRequest,
  options?: Parameters<typeof alertManagementFetch>[1],
): Promise<UpdateAlertRuleResult> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return alertManagementFetch<UpdateAlertRuleResult>(getUpdateAlertRuleUrl(ruleId), {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(updateAlertRuleRequest),
  });
};

